// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, address target, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(target != address(0));

        uint256 amt = bound(amount, 0, 1 ether);

        vm.deal(target, amt);
        vm.prank(target);
        c.addToBalance{value: amt}();

        uint256 actorAmt = amt / 2;
        vm.deal(actor, actorAmt);
        vm.prank(actor);
        c.addToBalance{value: actorAmt}();

        vm.prank(actor);
        uint256 reported = c.getBalance(target);

        vm.prank(target);
        uint256 actual = c.getBalance(target);

        assertTrue(reported == actual);
    }
}
